    private void setupLinkInterceptor(final android.webkit.WebView webview) {
        // ১. একটি জাদুকরী ব্রিজ তৈরি করা, যা জাভাস্ক্রিপ্ট থেকে ডাটা নেবে
        webview.addJavascriptInterface(new Object() {
            @android.webkit.JavascriptInterface
            public void handleExternalLink(String url) {
                runOnUiThread(() -> {
                    try {
                        // ২. ইনটেন্ট স্কিম হ্যান্ডেল করা (যেমন: intent://, tel:, mailto:)
                        android.content.Intent intent;
                        if (url.startsWith("intent://")) {
                            intent = android.content.Intent.parseUri(url, android.content.Intent.URI_INTENT_SCHEME);
                        } else {
                            intent = new android.content.Intent(android.content.Intent.ACTION_VIEW, android.net.Uri.parse(url));
                        }

                        if (intent != null) {
                            // অ্যাপটি ফোনে আছে কি না চেক করা
                            if (intent.resolveActivity(getPackageManager()) != null) {
                                startActivity(intent);
                            } else {
                                // অ্যাপ না থাকলে প্লে-স্টোর বা ফলব্যাক ইউআরএল
                                String packageName = intent.getPackage();
                                if (packageName != null) {
                                    startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW, 
                                        android.net.Uri.parse("market://details?id=" + packageName)));
                                }
                            }
                        }
                    } catch (Exception e) {
                        // কোনো এরর হলে শান্ত থাকা
                    }
                });
            }
        }, "NativeLinkHandler"); // ব্রিজের নাম

        // ৩. পেজের ভেতর ইন্টারসেপ্টর ইনজেক্ট করা (কোনো WebViewClient ছাড়াই)
        final android.os.Handler linkHandler = new android.os.Handler(android.os.Looper.getMainLooper());
        linkHandler.post(new Runnable() {
            @Override
            public void run() {
                // এই স্ক্রিপ্টটি সব লিঙ্কে নজর রাখবে
                String interceptorJS = "javascript:(function() { " +
                    "var links = document.getElementsByTagName('a'); " +
                    "for (var i = 0; i < links.length; i++) { " +
                    "  if (!links[i].getAttribute('data-linked')) { " +
                    "    links[i].setAttribute('data-linked', 'true'); " +
                    "    links[i].addEventListener('click', function(e) { " +
                    "      var href = this.href; " +
                    "      if (href && !href.startsWith('http')) { " +
                    "        e.preventDefault(); " +
                    "        NativeLinkHandler.handleExternalLink(href); " +
                    "      } " +
                    "    }); " +
                    "  } " +
                    "} " +
                    "})();";
                webview.evaluateJavascript(interceptorJS, null);

                // প্রতি ২ সেকেন্ড পর পর নতুন লিঙ্ক চেক করবে (ডাইনামিক সাইটের জন্য)
                linkHandler.postDelayed(this, 2000);
            }
        });
    }

